package com.digitalhealth.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.*; import java.util.*;
@Component public class TokenAuthenticationFilter extends OncePerRequestFilter { private final TokenService tokens; public TokenAuthenticationFilter(TokenService t){tokens=t;} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){AuthenticatedUser u=tokens.verify(h.substring(7));if(u!=null){var a=new UsernamePasswordAuthenticationToken(u,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.role())));SecurityContextHolder.getContext().setAuthentication(a);}}chain.doFilter(req,res);} }
